insert into public.indicator_submissions (id, contributor_id, indicator_type, value_norm, claimed_verdict) values ('00000000-0000-0000-0001-000000000010','00000000-0000-0000-0000-0000000000a4','domain','up.example.org','malicious');
insert into public.indicator_submissions (id, contributor_id, indicator_type, value_norm, claimed_verdict) values ('00000000-0000-0000-0001-000000000009','00000000-0000-0000-0000-0000000000a1','domain','up.example.org','malicious');
