reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000a2","role":"authenticated","aal":"aal2","app_metadata":{"role":"admin"},"is_anonymous":false}', true);
