reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000a2","role":"authenticated","aal":"aal2","app_metadata":{"role":"admin","is_platform_owner":true},"is_anonymous":false,"user_metadata":{"role":"owner","is_platform_owner":true}}', true);
select throws_ok($$select public.review_submission('00000000-0000-0000-0001-000000000001'::uuid,'approve','a long enough reason')$$,'P0001','self_review','client-supplied owner flags in the JWT are ignored');
