set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000a1","role":"authenticated","aal":"aal2","app_metadata":{"role":"admin"},"is_anonymous":false}', true);
select throws_ok($$select public.review_submission('00000000-0000-0000-0001-000000000003'::uuid,'approve',null)$$,'P0001','reason_required','self-review with missing reason is refused');
select throws_ok($$select public.review_submission('00000000-0000-0000-0001-000000000003'::uuid,'approve','')$$,'P0001','reason_required','self-review with empty reason is refused');
