select throws_ok($$select public.review_submission('00000000-0000-0000-0001-000000000003'::uuid,'approve','too short')$$,'P0001','reason_required','self-review with too short reason is refused');
select is((select count(*)::int from public.audit_log where target='00000000-0000-0000-0001-000000000003'::uuid),0,'refused self-reviews leave no audit row');
select is((select public.review_submission('00000000-0000-0000-0001-000000000002'::uuid,'approve','owner verified manually') ->> 'status'),'approved','owner can self-approve with a reason');
reset role;
select is((select review_kind||'/'||confidence::text||'/'||contributor_count::text from public.shared_indicators where value_norm='own-ok.example.org'),'self_reviewed/0.25/0','self-approved intel is labelled, low confidence, zero independent contributors');
select is((select action||'/'||decision||'/'||reason||'/'||self_review::text||'/'||actor::text from public.audit_log where target='00000000-0000-0000-0001-000000000002'::uuid),'self_approve/approve/owner verified manually/true/00000000-0000-0000-0000-0000000000a1','audit records actor, decision, reason and self-review flag');
select ok((select at is not null from public.audit_log where target='00000000-0000-0000-0001-000000000002'::uuid),'audit row is timestamped');
set local role anon;
select is((select review_kind from public.shared_indicators where value_norm='own-ok.example.org'),'self_reviewed','self-reviewed label is publicly readable');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-0000000000a1","role":"authenticated","aal":"aal2","app_metadata":{"role":"admin"},"is_anonymous":false}', true);
